/**
 * Longest exact wordmark phrase generated by the screening API.
 *
 * This is shared with the client-side field chunker: adjacent chunks overlap
 * by this value minus one so a registered phrase that crosses a boundary is
 * still sent whole. Keep the server candidate ceiling and the overlap aligned.
 */
export const MAX_TRADEMARK_WORDS = 12;

/**
 * Max words of text per /api/v1/check request.
 *
 * The server expands each request into exact phrases up to
 * MAX_TRADEMARK_WORDS, caps the full candidate set at 2,000, and splits DB
 * lookups into bounded 500-candidate RPC calls. At 80 words, even a worst-case
 * set with plural variants stays comfortably below the request cap.
 *
 * SINGLE SOURCE OF TRUTH. Both request paths chunk to this value:
 *   - the core keyword screen  (screenTermsForTrademarks, this package)
 *   - the extension page-scanner (extension/scan-core.ts, via a relative import)
 * They were 80 vs 110 before this was centralized — two magic numbers for one
 * server contract, free to drift. Keep them one.
 */
export const MAX_WORDS_PER_CHECK_REQUEST = 80;
